import React from 'react';

const HoldingsTable = ({ holdings }) => {
    if (!holdings || holdings.length === 0) {
        return (
            <div style={{
                background: '#141b2b',
                padding: '30px',
                borderRadius: '10px',
                border: '1px solid #2a3a5c',
                textAlign: 'center'
            }}>
                <p style={{ color: '#8a9bb5' }}>📭 No holdings yet. Start trading!</p>
            </div>
        );
    }

    return (
        <div style={{
            background: '#141b2b',
            padding: '15px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c',
            overflowX: 'auto'
        }}>
            <h3 style={{ marginBottom: '15px', color: '#e0e6ed' }}>📊 Holdings</h3>
            
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                    <tr style={{ color: '#8a9bb5', fontSize: '13px', borderBottom: '1px solid #2a3a5c' }}>
                        <th style={{ padding: '10px', textAlign: 'left' }}>Symbol</th>
                        <th style={{ padding: '10px', textAlign: 'right' }}>Qty</th>
                        <th style={{ padding: '10px', textAlign: 'right' }}>Avg Price</th>
                        <th style={{ padding: '10px', textAlign: 'right' }}>Current</th>
                        <th style={{ padding: '10px', textAlign: 'right' }}>Value</th>
                        <th style={{ padding: '10px', textAlign: 'right' }}>P&L</th>
                        <th style={{ padding: '10px', textAlign: 'right' }}>P&L %</th>
                    </tr>
                </thead>
                <tbody>
                    {holdings.map((item) => (
                        <tr key={item.symbol} style={{ borderBottom: '1px solid #2a3a5c' }}>
                            <td style={{ padding: '10px', fontWeight: 'bold' }}>{item.symbol}</td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>{item.quantity}</td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>₹{item.avg_price.toFixed(2)}</td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>₹{item.current_price.toFixed(2)}</td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>₹{item.current_value.toFixed(2)}</td>
                            <td style={{
                                padding: '10px',
                                textAlign: 'right',
                                color: item.pnl >= 0 ? '#4CAF50' : '#dc3545',
                                fontWeight: 'bold'
                            }}>
                                {item.pnl >= 0 ? '+' : ''}₹{item.pnl.toFixed(2)}
                            </td>
                            <td style={{
                                padding: '10px',
                                textAlign: 'right',
                                color: item.pnl_percent >= 0 ? '#4CAF50' : '#dc3545',
                                fontWeight: 'bold'
                            }}>
                                {item.pnl_percent >= 0 ? '+' : ''}{item.pnl_percent.toFixed(2)}%
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

export default HoldingsTable;
